CREATE TYPE "NewsSport" AS ENUM ('FOOTBALL', 'BASKETBALL');
CREATE TYPE "CommentableType" AS ENUM ('NEWS_ARTICLE', 'MATCH', 'PREDICTION');
CREATE TYPE "CommentStatus" AS ENUM ('VISIBLE', 'HIDDEN', 'DELETED');
CREATE TABLE "NewsArticle" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "sport" "NewsSport" NOT NULL, "category" TEXT, "sourceName" TEXT NOT NULL, "sourceUrl" TEXT NOT NULL, "title" TEXT NOT NULL, "excerpt" TEXT, "imageUrl" TEXT, "publishedAt" TIMESTAMP(3), "syncedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "NewsArticle_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "NewsArticle_slug_key" ON "NewsArticle"("slug"); CREATE UNIQUE INDEX "NewsArticle_sourceUrl_key" ON "NewsArticle"("sourceUrl"); CREATE INDEX "NewsArticle_sport_category_publishedAt_idx" ON "NewsArticle"("sport", "category", "publishedAt");
CREATE TABLE "Comment" ("id" TEXT NOT NULL, "content" VARCHAR(2000) NOT NULL, "userId" TEXT NOT NULL, "entityType" "CommentableType" NOT NULL, "entityId" TEXT NOT NULL, "parentId" TEXT, "depth" INTEGER NOT NULL DEFAULT 0, "status" "CommentStatus" NOT NULL DEFAULT 'VISIBLE', "isEdited" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Comment_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Comment" ADD CONSTRAINT "Comment_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Comment" ADD CONSTRAINT "Comment_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "Comment"("id") ON DELETE SET NULL ON UPDATE CASCADE; CREATE INDEX "Comment_entityType_entityId_status_createdAt_idx" ON "Comment"("entityType", "entityId", "status", "createdAt"); CREATE INDEX "Comment_parentId_idx" ON "Comment"("parentId");
CREATE TABLE "CommentReport" ("id" TEXT NOT NULL, "commentId" TEXT NOT NULL, "reporterId" TEXT NOT NULL, "reason" VARCHAR(500) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CommentReport_pkey" PRIMARY KEY ("id")); ALTER TABLE "CommentReport" ADD CONSTRAINT "CommentReport_commentId_fkey" FOREIGN KEY ("commentId") REFERENCES "Comment"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CommentReport" ADD CONSTRAINT "CommentReport_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; CREATE UNIQUE INDEX "CommentReport_commentId_reporterId_key" ON "CommentReport"("commentId", "reporterId");
